import React, { useState, useEffect } from "react";
import { firestore } from "./firebase";
import { deleteDoc, doc, collection, addDoc, onSnapshot, query, orderBy, where, getDocs } from "firebase/firestore";
import { HashRouter as Router, Route, Routes, useNavigate, useLocation } from "react-router-dom";
import "./App.css";
import LoginPage from "./components/LoginPage";
import Sidebar from "./components/Sidebar";
import Task from "./components/Task";
import Confirm from "./components/Confirm";
import Home from "./components/Home";
import CalendarComponent from './components/Calendar';
import Reservation from "./components/Reservation";

function App() {
  const [userId, setUserId] = useState("");
  const [password, setPassword] = useState("");
  const [userName, setUserName] = useState("");
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [tasks, setTasks] = useState([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (isLoggedIn) {
      const tasksCollection = collection(firestore, "tasks");
      const tasksQuery = query(tasksCollection, orderBy("createdAt", "asc"));
      const unsubscribe = onSnapshot(tasksQuery, (snapshot) => {
        setTasks(snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
      });
      return () => unsubscribe();
    }
  }, [isLoggedIn]);

  useEffect(() => {
    const savedUserId = localStorage.getItem("userId");
    const savedUserName = localStorage.getItem("userName");

    if (savedUserId && savedUserName) {
      setUserId(savedUserId);
      setUserName(savedUserName);
      setIsLoggedIn(true);

      const validRoutes = ["/home", "/task", "/calendar", "/reservation"];
      const currentPath = location.pathname;

      if (!validRoutes.includes(currentPath)) {
        navigate("/home");
      }
    }
    // 下のコメントはuseEffectの第二引数に何も入れていないとエラーになるので、無視するという意味
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleLogin = async (e, setErrorMessage) => {
    e.preventDefault();
    setErrorMessage("");

    const userRef = collection(firestore, "users");
    const userQuery = query(userRef, where("userId", "==", userId), where("password", "==", password));
    const userSnapshot = await getDocs(userQuery);

    if (!userSnapshot.empty) {
      setUserName(userSnapshot.docs[0].data().userName);
      localStorage.setItem("userId", userId);
      localStorage.setItem("userName", userSnapshot.docs[0].data().userName);
      setIsLoggedIn(true);
      navigate("/home");
      return true;
    } else {
      setErrorMessage("ユーザーIDまたはパスワードが間違っています");
      return false;
    }
  };

  const handleLogout = () => {
    setUserId("");
    setPassword("");
    setUserName("");
    setTasks([]);
    localStorage.removeItem("userId");
    localStorage.removeItem("userName");
    setIsLoggedIn(false);
    navigate("/");
    setIsConfirmOpen(false);
    setIsSidebarOpen(false);
  };

  const toggleSidebar = () => {
    setIsSidebarOpen(!isSidebarOpen);
  };

  const handleAddTask = async (taskData) => {
    try {
      await addDoc(collection(firestore, "tasks"), {
        name: taskData.name,
        user: taskData.user,
        priority: taskData.priority,
        createdAt: new Date(),
      });
    } catch (error) {
      console.log("タスク追加エラー:" + error);
    }
  };

  const handleDeleteTask = async (id) => {
    try {
      await deleteDoc(doc(firestore, "tasks", id));
    } catch (error) {
      console.log("タスク削除エラー:" + error);
    }
  };

  const openConfirm = () => {
    setIsConfirmOpen(true);
  };

  const closeConfirm = () => {
    setIsConfirmOpen(false);
  };

  return (
    <div>
      {!isLoggedIn ? (
        <LoginPage
          handleLogin={handleLogin}
          userId={userId}
          setUserId={setUserId}
          password={password}
          setPassword={setPassword}
        />
      ) : (
        <div className="WebApp">
          <button className="menu-toggle" onClick={toggleSidebar}>
            {isSidebarOpen ? "✕" : "☰"}
          </button>
          <Sidebar
            userName={userName}
            handleLogout={openConfirm}
            isOpen={isSidebarOpen}
            toggleSidebar={toggleSidebar}
          />
          <div className={`main-content ${location.pathname === "/home" ? "no-padding" : ""}`}>
            <Routes>
              <Route
                path="/home"
                element={
                  <Home
                    version="0.4.1"
                    lastUpdated="2025-04-21"
                    notice="予約画面を見やすくしました！"
                    targetDate="2025-09-28T13:00:00"
                  />
                }
              />
              <Route
                path="/task"
                element={
                  <Task
                    handleAddTask={handleAddTask}
                    tasks={tasks}
                    handleDeleteTask={handleDeleteTask}
                    userName={userName}
                  />
                }
              />
              <Route
                path="/calendar"
                element={
                  <CalendarComponent initialUserName={userName}/>
                }
              />
              <Route
                path="reservation"
                element={
                  <Reservation/>
                }
              />
            </Routes>
          </div>
          {isConfirmOpen && (
            <Confirm
              message="本当にログアウトしますか？"
              onConfirm={handleLogout}
              onCancel={closeConfirm}
            />
          )}
        </div>
      )}
    </div>
  );
}

export default function WrappedApp() {
  return (
    <Router>
      <App />
    </Router>
  );
}
